import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    tau_n = 1
    for p, a in factors.items():
        tau_n *= (a + 1)
    return tau_n

def calculate_tau_x(x):
    # tau(x) = (tau(x^2) - 1) / 2
    x_squared = x * x
    tau_x_squared = tau(x_squared)
    # Since tau(x^2) must be odd (product of odd numbers 2a+1), tau(x^2) - 1 is even.
    return (tau_x_squared - 1) // 2

# Testing known candidates
candidates = [1, 2, 3, 4, 6, 12, 720, 840, 1008, 1152, 960, 1260, 1680]
results = {}
for x in candidates:
    results[x] = calculate_tau_x(x)

print("Testing structured candidates:")
print(results)

import math

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

